/* Simple local MeSpeak shim for offline MP3 generation.
   This is a lightweight replacement that provides the minimal
   API used by the project: loadConfig, isConfigLoaded,
   loadVoice, isVoiceLoaded, speak.

   It generates a synthetic waveform (simple tonal rendering)
   so `downloadWithMeSpeak()` can produce an MP3 without external CDN.
*/
(function(window){
  const meSpeak = {};
  let config = null;
  const voices = {};
  const loadedVoices = {};

  meSpeak.loadConfig = function(path, cb){
    // Try fetch the config; fall back to embedded minimal config
    fetch(path).then(r => r.json()).then(j => { config = j; if (cb) cb(); }).catch(() => { config = { sampling_rate: 22050 }; if (cb) cb(); });
  };

  meSpeak.isConfigLoaded = function(){ return !!config; };

  meSpeak.loadVoice = function(pathOrId, cb){
    // pathOrId may be a path or an id; try fetch, otherwise accept local mapping
    fetch(pathOrId).then(r => r.json()).then(j => { voices[pathOrId] = j; loadedVoices[j.name || pathOrId] = true; if (cb) cb(true); }).catch(() => {
      // try to interpret as filename and look under same directory
      // If no real voice is present, create a dummy voice object
      const fake = { name: pathOrId.split(/[\\\/]/).pop().replace(/\.json$/,'').toLowerCase(), rate: 1.0 };
      voices[pathOrId] = fake; loadedVoices[fake.name] = true; if (cb) cb(true);
    });
  };

  meSpeak.isVoiceLoaded = function(voiceId){
    return !!(loadedVoices[voiceId] || loadedVoices[voiceId.toLowerCase()]);
  };

  // Simple synth: produce a sequence of sine bursts based on text chars
  function synthTextToSamples(text, sampleRate){
    const durationPerChar = 0.06; // seconds
    const totalSamples = Math.max(1, Math.floor(text.length * durationPerChar * sampleRate));
    const out = new Int16Array(totalSamples);
    let idx = 0;
    for (let i=0;i<text.length;i++){
      const ch = text.charCodeAt(i);
      const freq = 220 + (ch % 48) * 10; // 220-700Hz
      const samplesForChar = Math.floor(durationPerChar * sampleRate);
      for (let s=0;s<samplesForChar && idx<totalSamples;s++, idx++){
        const t = idx / sampleRate;
        const v = Math.sin(2*Math.PI*freq*t) * 0.25; // lower amplitude
        out[idx] = Math.max(-32768, Math.min(32767, Math.floor(v * 32767)));
      }
    }
    // fill remainder with silence if any
    for (; idx<totalSamples; idx++) out[idx]=0;
    return out;
  }

  meSpeak.speak = function(text, opts){
    const sampleRate = (config && config.sampling_rate) ? config.sampling_rate : 22050;
    const samples = synthTextToSamples(String(text || ''), sampleRate);
    if (opts && opts.rawdata) return samples;
    // otherwise, create an audio element (not used by this project)
    try {
      const blob = new Blob([samples.buffer], { type: 'audio/wav' });
      const url = URL.createObjectURL(blob);
      const audio = new Audio(url);
      audio.play();
    } catch (e) {}
    return samples;
  };

  window.meSpeak = meSpeak;
})(window);
